import{_ as i,l as s,o as e,c as l,v as o,p as n,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"Boyer–Moore","description":"","frontmatter":{"title":"Boyer–Moore","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/boyer-moore.md","filePath":"cs/boyer-moore.md","lastUpdated":1789023840000}'),c={name:"cs/boyer-moore.md"};function m(B,a,A,E,M,P){const t=s("Mermaid");return e(),l("div",null,[a[1]||(a[1]=o('<h1 id="boyer–moore" tabindex="-1">Boyer–Moore <a class="header-anchor" href="#boyer–moore" aria-label="Permalink to &quot;Boyer–Moore&quot;">​</a></h1><div class="epigraph"><p>模式从右往左比；失配时坏字符与好后缀规则可以把模式向右滑出多格，文本指针不必像朴素那样只走一格。</p><footer>—— 据 Boyer and Moore, A Fast String Searching Algorithm, 1977；CLRS 第 32 章整理</footer></div><p>上一课<a href="/cs/kmp">KMP 串匹配</a>预处理模式的前缀函数，扫描文本只前进，最坏 \\(\\Theta(n+m)\\)。本课不重算 \\(\\pi\\)。缺口是另一条工程主路：对齐窗口内<strong>从右端比</strong>，用失配字符在模式中的最后出现、以及已匹配后缀的重现，计算滑步。平均常亚线性扫描文本；最坏仍须小心，本课钉规则不把所有最坏变体写完。后课多模式换成自动机。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>KMP 保证最坏线性，文本每个字符都进转移。Boyer–Moore：窗口右端对齐，先比 \\(P\\) 的末字符。若 \\(T\\) 该位是 \\(c\\) 且 \\(P\\) 末位不是 \\(c\\)，把 \\(P\\) 滑到使某次出现的 \\(c\\) 对齐（没有则整模式滑过 \\(c\\)）——坏字符规则。若已匹配了一段后缀，好后缀规则滑到该后缀在 \\(P\\) 中的上一次出现，或滑到与后缀一致的前缀。两规则取较大步。</p><p>缺口是「可以跳着读 \\(T\\)」，不是哈希。仍要确定性、精确匹配。字母表大时坏字符常一步跨很远；字母表小、模式周期强时好后缀更关键。</p><h3 id="从右比不是「倒着跑-kmp」" tabindex="-1">从右比不是「倒着跑 KMP」 <a class="header-anchor" href="#从右比不是「倒着跑-kmp」" aria-label="Permalink to &quot;从右比不是「倒着跑 KMP」&quot;">​</a></h3><p>KMP 的 \\(\\pi\\) 来自前缀自匹配。BM 的表来自字符出现位置与后缀重现。不要把 \\(\\pi[q]\\) 当坏字符位移。Sunday、Horspool 是简化：只用坏字符的变体，本课点名不展开。</p><p><span class="marginnote">Boyer–Moore 1977，CACM。CLRS 第 32 章以 KMP 为主，BM 作注释级对照。本课把它收进主干，因为词法与检索实现经常先写 BM/Horspool。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>预处理：每个字符在 \\(P\\) 中最右下标；好后缀表（对每个已匹配长度的滑步）。匹配：对齐 \\(s\\)，从 \\(P\\) 右端比较；全中则报告，\\(s\\) 再加好后缀步找下一处；失配取两规则最大值更新 \\(s\\)。</p>',11)),(e(),n(h,null,{default:r(()=>[d(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIN%5B%22%E7%AA%97%E5%8F%A3%E5%8F%B3%E5%AF%B9%E9%BD%90%22%5D%20--%3E%20CMP%5B%22%E4%BB%8E%E5%8F%B3%E6%AF%94%E8%BE%83%22%5D%0A%20%20CMP%20--%3E%20BC%5B%22%E5%9D%8F%E5%AD%97%E7%AC%A6%E6%BB%91%E6%AD%A5%22%5D%0A%20%20CMP%20--%3E%20GS%5B%22%E5%A5%BD%E5%90%8E%E7%BC%80%E6%BB%91%E6%AD%A5%22%5D%0A%20%20BC%20--%3E%20MAX%5B%22%E5%8F%96%E8%BE%83%E5%A4%A7%E6%AD%A5%22%5D%0A%20%20GS%20--%3E%20MAX%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<p>预处理 \\(O(m+|\\Sigma|)\\) 量级。不要在未预处理时「每次现算最右出现」而不摊到表上——那会把常数写乱，渐近仍可，但不是本课的算法。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>亚线性：许多窗口只读右端一个字符。最坏可到 \\(\\Theta(nm)\\)（某些教材变体）；Galil 规则等补丁回到线性，本课点名：要最坏线性，KMP 更干净。本课对象是精确单模式；正则仍是编译课。</p><p>与<a href="/cs/hash-function">散列</a>：Rabin–Karp 是滚动指纹，模型不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不做近似匹配、不写二维。多模式下一课 Aho–Corasick 一次扫 \\(T\\)。后课默认：单模式精确，KMP 最坏线性，BM 平均跳读。多模式共享前缀时不要对每个 \\(P\\) 各跑一遍 BM。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>BM 从右比，坏字符与好后缀决定滑步。</li><li>平均常少读 \\(T\\)；最坏线性仍以 KMP 为定理级保证。</li><li>单模式；多模式是下一课自动机。</li><li>出处：Boyer and Moore, 1977；CLRS 第 32 章。</li></ul>',8))])}const f=i(c,[["render",m]]);export{u as __pageData,f as default};
